"""Abstraction function and business invariants for rq (Redis Queue).

Lower level: a snapshot of the Redis keys rq writes.
Upper level: queues with the jobs waiting in them, the job registries of
each queue, the jobs with their status, executions and results, and the
workers with the job each one is running.
"""

import json

_REGISTRY_PREFIXES = (
    ("rq:wip:", "started"),
    ("rq:finished:", "finished"),
    ("rq:failed:", "failed"),
    ("rq:deferred:", "deferred"),
    ("rq:scheduled:", "scheduled"),
    ("rq:canceled:", "canceled"),
)
_REGISTRY_KINDS = tuple(kind for _, kind in _REGISTRY_PREFIXES)

# The registry in which a job with a given status is expected to be listed.
_STATUS_REGISTRY = {
    "started": "started",
    "finished": "finished",
    "failed": "failed",
    "stopped": "failed",
    "deferred": "deferred",
    "scheduled": "scheduled",
    "canceled": "canceled",
}

_RESULT_TYPES = {
    "1": "successful",
    "2": "failed",
    "3": "stopped",
    "4": "retried",
    "5": "max_retries_exceeded",
}


# --------------------------------------------------------------------------
# small, never-raising helpers
# --------------------------------------------------------------------------

def _opt(x):
    """A non-empty string, or None."""
    return x if isinstance(x, str) and x != "" else None


def _int(x):
    if isinstance(x, int) and not isinstance(x, bool):
        return x
    if isinstance(x, str):
        try:
            return int(x)
        except ValueError:
            try:
                f = float(x)
                return int(f) if f == int(f) else f
            except (ValueError, OverflowError):
                return x
    return None


def _strs(v):
    if not isinstance(v, list):
        return []
    return [x for x in v if isinstance(x, str)]


def _zmembers(v):
    if not isinstance(v, list):
        return []
    out = []
    for item in v:
        if isinstance(item, (list, tuple)) and item and isinstance(item[0], str):
            out.append(item[0])
        elif isinstance(item, str):
            out.append(item)
    return out


def _json_list(x):
    if not isinstance(x, str) or not x:
        return None
    try:
        v = json.loads(x)
    except (ValueError, TypeError):
        return None
    if isinstance(v, list):
        return [str(i) for i in v]
    return None


# --------------------------------------------------------------------------
# reading the snapshot
# --------------------------------------------------------------------------

def _read(snap):
    if not isinstance(snap, dict):
        snap = {}

    m = {
        "registered_queues": set(),
        "waiting": {},          # queue -> [job ids] (in queue order)
        "picking": {},          # queue -> [job ids] dequeued, not yet started
        "registries": {k: {} for k in _REGISTRY_KINDS},  # kind -> queue -> [entries]
        "job_hashes": {},
        "dependents": {},       # job -> [jobs that depend on it]
        "dependency_sets": {},  # job -> [jobs it depends on]
        "executions": {},       # job -> {execution id: worker}
        "results": {},          # job -> [stream entries]
        "workers": {},          # name -> hash
    }

    for key in sorted(k for k in snap if isinstance(k, str)):
        e = snap.get(key)
        if not isinstance(e, dict):
            continue
        t = e.get("t")
        v = e.get("v")

        if key == "rq:queues":
            if t == "set":
                for name in _strs(v):
                    if name.startswith("rq:queue:"):
                        m["registered_queues"].add(name[len("rq:queue:"):])
            continue

        if key.startswith("rq:queue:"):
            if t == "list":
                rest = key[len("rq:queue:"):]
                if rest.endswith(":intermediate"):
                    m["picking"][rest[: -len(":intermediate")]] = _strs(v)
                else:
                    m["waiting"][rest] = _strs(v)
            continue

        matched = False
        for prefix, kind in _REGISTRY_PREFIXES:
            if key.startswith(prefix):
                matched = True
                if t == "zset":
                    m["registries"][kind][key[len(prefix):]] = _zmembers(v)
                break
        if matched:
            continue

        if key.startswith("rq:job:"):
            rest = key[len("rq:job:"):]
            if t == "hash" and rest and ":" not in rest:
                m["job_hashes"][rest] = v if isinstance(v, dict) else {}
            elif t == "set" and rest.startswith(":") and rest.endswith(":dependencies"):
                jid = rest[1: -len(":dependencies")]
                if jid:
                    m["dependency_sets"][jid] = _strs(v)
            elif t == "set" and rest.endswith(":dependents") and not rest.startswith(":"):
                jid = rest[: -len(":dependents")]
                if jid:
                    m["dependents"][jid] = _strs(v)
            continue

        if key.startswith("rq:execution:"):
            if t == "hash":
                h = v if isinstance(v, dict) else {}
                jid, _, xid = key[len("rq:execution:"):].partition(":")
                xid = xid or _opt(h.get("id")) or ""
                if jid:
                    m["executions"].setdefault(jid, {})[xid] = _opt(h.get("worker_name"))
            continue

        if key.startswith("rq:results:"):
            if t == "stream":
                jid = key[len("rq:results:"):]
                m["results"][jid] = [x for x in v if isinstance(x, dict)] if isinstance(v, list) else []
            continue

        if key.startswith("rq:worker:"):
            if t == "hash":
                name = key[len("rq:worker:"):]
                if name:
                    m["workers"][name] = v if isinstance(v, dict) else {}
            continue

    return snap, m


def _result_view(entry):
    raw = entry.get("type")
    r = {
        "type": _RESULT_TYPES.get(raw, "type_" + str(raw)) if raw is not None else "unknown",
        "execution": _opt(entry.get("execution_id")),
        "worker": _opt(entry.get("worker_name")),
    }
    if "return_value" in entry:
        r["return_value"] = entry.get("return_value")
    if _opt(entry.get("exc_string")):
        r["exception"] = entry.get("exc_string")
    return r


def _build(snap):
    snap, m = _read(snap)

    jobs = {}
    unreadable = []
    for jid in sorted(m["job_hashes"]):
        h = m["job_hashes"][jid]
        if "data" not in h:
            # Only stray fields (e.g. a heartbeat written after deletion): rq
            # cannot load this as a job.
            unreadable.append(jid)
            continue
        depends_on = _json_list(h.get("dependency_ids"))
        if depends_on is None:
            dep = _opt(h.get("dependency_id"))
            depends_on = [dep] if dep else sorted(m["dependency_sets"].get(jid, []))
        callbacks = {}
        for kind in ("success", "failure", "stopped"):
            name = _opt(h.get(kind + "_callback_name"))
            if name:
                callbacks["on_" + kind] = name
        entry = snap.get("rq:job:" + jid)
        execs = m["executions"].get(jid, {})
        allow = h.get("allow_dependency_failures")
        jobs[jid] = {
            "status": _opt(h.get("status")) or "created",
            "queue": _opt(h.get("origin")),
            "description": _opt(h.get("description")),
            "worker": _opt(h.get("worker_name")),
            "enqueued_at": _opt(h.get("enqueued_at")),
            "started_at": _opt(h.get("started_at")),
            "ended_at": _opt(h.get("ended_at")),
            "depends_on": list(depends_on),
            "dependents": sorted(m["dependents"].get(jid, [])),
            "allow_dependency_failures": bool(_int(allow)) if _opt(allow) else False,
            "timeout": _int(h.get("timeout")) if _opt(h.get("timeout")) else None,
            "result_ttl": _int(h.get("result_ttl")) if _opt(h.get("result_ttl")) else None,
            "failure_ttl": _int(h.get("failure_ttl")) if _opt(h.get("failure_ttl")) else None,
            "ttl": _int(h.get("ttl")) if _opt(h.get("ttl")) else None,
            "retries_left": _int(h.get("retries_left")) if _opt(h.get("retries_left")) else None,
            "number_of_retries": _int(h.get("number_of_retries")) if _opt(h.get("number_of_retries")) else None,
            "repeats_left": _int(h.get("repeats_left")) if _opt(h.get("repeats_left")) else None,
            "group": _opt(h.get("group_id")),
            "callbacks": callbacks,
            "expires": bool(isinstance(entry, dict) and entry.get("ttl")),
            "executions": [{"id": x, "worker": execs[x]} for x in sorted(execs)],
            "results": [_result_view(r) for r in m["results"].get(jid, [])],
        }

    # Started registry entries are "<job id>:<execution id>".
    started_pairs = {}
    for q, entries in m["registries"]["started"].items():
        pairs = []
        for e in entries:
            jid, _, xid = e.partition(":")
            pairs.append((jid, xid))
        started_pairs[q] = pairs

    queue_names = set(m["registered_queues"]) | set(m["waiting"]) | set(m["picking"])
    for kind in _REGISTRY_KINDS:
        queue_names |= set(m["registries"][kind])
    for j in jobs.values():
        if j["queue"]:
            queue_names.add(j["queue"])

    queues = {}
    for q in sorted(queue_names):
        info = {
            "registered": q in m["registered_queues"],
            "waiting": list(m["waiting"].get(q, [])),
            "being_picked_up": list(m["picking"].get(q, [])),
            "started": sorted(jid for jid, _ in started_pairs.get(q, [])),
        }
        for kind in _REGISTRY_KINDS:
            if kind != "started":
                info[kind] = sorted(m["registries"][kind].get(q, []))
        queues[q] = info

    workers = {}
    for name in sorted(m["workers"]):
        h = m["workers"][name]
        w = {
            "state": _opt(h.get("state")),
            "current_job": _opt(h.get("current_job")),
            "successful_jobs": _int(h.get("successful_job_count")) if _opt(h.get("successful_job_count")) else 0,
            "failed_jobs": _int(h.get("failed_job_count")) if _opt(h.get("failed_job_count")) else 0,
        }
        if _opt(h.get("queues")):
            w["queues"] = [x for x in h["queues"].split(",") if x]
        workers[name] = w

    return {
        "m": m,
        "jobs": jobs,
        "unreadable": unreadable,
        "queues": queues,
        "workers": workers,
        "started_pairs": started_pairs,
    }


# --------------------------------------------------------------------------
# public API
# --------------------------------------------------------------------------

def abstract(snap: dict) -> dict:
    """Business-level state, as {variable name: JSON-serialisable value}."""
    try:
        b = _build(snap)
    except Exception:  # defensive: never raise on a snapshot
        return {"queues": {}, "jobs": {}, "workers": {}, "unreadable_jobs": []}
    return {
        "queues": b["queues"],
        "jobs": b["jobs"],
        "workers": b["workers"],
        "unreadable_jobs": b["unreadable"],
    }


def invariants(snap: dict) -> dict:
    """Business invariants, as {invariant name: bool}; True means it holds."""
    try:
        return _invariants(_build(snap))
    except Exception:  # defensive: never raise on a snapshot
        return {"snapshot_is_understandable": False}


def _invariants(b):
    m = b["m"]
    J = b["jobs"]
    workers = b["workers"]
    started_pairs = b["started_pairs"]

    def st(j):
        return J[j]["status"]

    def origin(j):
        return J[j]["queue"]

    in_waiting = {}
    for q, ids in m["waiting"].items():
        for j in ids:
            in_waiting.setdefault(j, []).append(q)
    in_picking = {}
    for q, ids in m["picking"].items():
        for j in ids:
            in_picking.setdefault(j, []).append(q)

    reg_jobs = {k: {} for k in _REGISTRY_KINDS}
    for q, pairs in started_pairs.items():
        reg_jobs["started"][q] = [j for j, _ in pairs]
    for kind in _REGISTRY_KINDS:
        if kind != "started":
            for q, ids in m["registries"][kind].items():
                reg_jobs[kind][q] = list(ids)

    def in_reg(kind, q, j):
        return q is not None and j in reg_jobs[kind].get(q, ())

    running_on = {}
    for name, w in workers.items():
        if w["current_job"]:
            running_on.setdefault(w["current_job"], []).append(name)

    inv = {}

    # ---- queues -----------------------------------------------------------
    inv["every_queued_job_is_waiting_in_its_queue"] = all(
        origin(j) in in_waiting.get(j, [])
        or origin(j) in in_picking.get(j, [])
        or bool(J[j]["executions"])
        for j in J if st(j) == "queued"
    )
    inv["jobs_waiting_in_a_queue_are_queued"] = all(
        st(j) == "queued" for j in list(in_waiting) + list(in_picking) if j in J
    )
    inv["queues_only_hold_existing_jobs"] = all(j in J for j in in_waiting)
    inv["jobs_wait_in_their_own_queue"] = all(
        all(q == origin(j) for q in in_waiting[j]) for j in in_waiting if j in J
    )
    inv["no_job_waits_twice"] = all(
        len(in_waiting.get(j, [])) + len(in_picking.get(j, [])) <= 1
        for j in set(in_waiting) | set(in_picking)
    )
    inv["queues_in_use_are_registered"] = all(
        q in m["registered_queues"] for q, ids in m["waiting"].items() if ids
    ) and all(
        origin(j) in m["registered_queues"]
        for j in J if origin(j) and st(j) not in ("created",)
    )

    # ---- running jobs -----------------------------------------------------
    inv["every_started_job_is_running"] = all(
        in_reg("started", origin(j), j) and bool(J[j]["executions"]) and J[j]["worker"] is not None
        for j in J if st(j) == "started"
    )
    inv["started_registry_holds_only_running_jobs"] = all(
        j in J and st(j) in ("started", "queued") and origin(j) == q
        for q, ids in reg_jobs["started"].items() for j in ids
    )
    inv["workers_only_run_started_jobs"] = all(
        w["current_job"] in J
        and st(w["current_job"]) == "started"
        and J[w["current_job"]]["worker"] == name
        for name, w in workers.items() if w["current_job"]
    )
    started_count = {}
    for ids in reg_jobs["started"].values():
        for j in ids:
            started_count[j] = started_count.get(j, 0) + 1
    inv["a_job_runs_at_most_once_at_a_time"] = (
        all(len(J[j]["executions"]) <= 1 for j in J)
        and all(len(ws) <= 1 for ws in running_on.values())
        and all(c <= 1 for c in started_count.values())
    )
    inv["executions_belong_to_existing_jobs"] = all(j in J for j in m["executions"] if m["executions"][j])
    inv["executions_are_tracked_as_started"] = all(
        (j, x) in started_pairs.get(origin(j), [])
        for j in J for x in m["executions"].get(j, {})
    )

    # ---- registries match statuses -----------------------------------------
    for kind in ("finished", "failed", "deferred", "scheduled", "canceled"):
        allowed = {s for s, k in _STATUS_REGISTRY.items() if k == kind}
        inv[kind + "_registry_holds_only_" + kind + "_jobs"] = all(
            st(j) in allowed and origin(j) == q
            for q, ids in reg_jobs[kind].items() for j in ids if j in J
        )
    inv["jobs_are_listed_in_the_registry_for_their_status"] = all(
        in_reg(_STATUS_REGISTRY[st(j)], origin(j), j)
        for j in J if st(j) in _STATUS_REGISTRY and st(j) != "started"
    )
    places = {}
    for j, qs in in_waiting.items():
        places[j] = places.get(j, 0) + len(qs)
    for kind in _REGISTRY_KINDS:
        for ids in reg_jobs[kind].values():
            for j in set(ids):
                places[j] = places.get(j, 0) + 1
    inv["each_job_is_in_one_place"] = all(c <= 1 for c in places.values())

    # ---- outcomes ---------------------------------------------------------
    inv["finished_jobs_have_a_successful_result"] = all(
        bool(J[j]["results"]) and J[j]["results"][-1]["type"] == "successful"
        for j in J if st(j) == "finished"
    )
    inv["failed_jobs_have_a_failure_result"] = all(
        bool(J[j]["results"]) and J[j]["results"][-1]["type"] != "successful"
        for j in J if st(j) in ("failed", "stopped")
    )
    inv["finished_jobs_have_an_end_time"] = all(
        J[j]["ended_at"] is not None for j in J if st(j) == "finished"
    )
    inv["canceled_jobs_are_neither_waiting_nor_running"] = all(
        j not in in_waiting
        and j not in in_picking
        and started_count.get(j, 0) == 0
        and j not in running_on
        and not J[j]["executions"]
        for j in J if st(j) == "canceled"
    )

    # ---- dependencies -----------------------------------------------------
    inv["deferred_jobs_have_dependencies"] = all(
        bool(J[j]["depends_on"]) for j in J if st(j) == "deferred"
    )
    inv["dependency_links_agree"] = all(
        parent in J[kid]["depends_on"]
        for parent, kids in m["dependents"].items() for kid in kids if kid in J
    )

    # ---- data integrity ---------------------------------------------------
    inv["all_jobs_are_readable"] = not b["unreadable"]

    return inv
